/**
 * Pure JS HMAC-SHA256 (hex). Works in n8n task-runner sandboxes without require('crypto').
 */
function hmacSha256Hex(message, key, hexChars = 64) {
  function toBytes(str) {
    if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(str)
    const out = []
    for (let i = 0; i < str.length; i++) {
      let c = str.charCodeAt(i)
      if (c < 0x80) out.push(c)
      else if (c < 0x800) {
        out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f))
      } else if (c >= 0xd800 && c < 0xdc00) {
        const c2 = str.charCodeAt(++i)
        const u = 0x10000 + ((c & 0x3ff) << 10) + (c2 & 0x3ff)
        out.push(
          0xf0 | (u >> 18),
          0x80 | ((u >> 12) & 0x3f),
          0x80 | ((u >> 6) & 0x3f),
          0x80 | (u & 0x3f),
        )
      } else {
        out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f))
      }
    }
    return new Uint8Array(out)
  }

  function rotr(n, x) {
    return (x >>> n) | (x << (32 - n))
  }

  function sha256Bytes(data) {
    const K = [
      0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
      0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
      0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
      0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
      0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
      0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
      0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
      0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ]
    const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
    const l = data.length
    const withOne = l + 1
    const padLen = (withOne % 64 <= 56 ? 56 : 120) - (withOne % 64) + withOne
    const total = padLen + 8
    const buf = new Uint8Array(total)
    buf.set(data)
    buf[l] = 0x80
    const bitLen = l * 8
    const view = new DataView(buf.buffer)
    view.setUint32(total - 4, bitLen >>> 0)
    view.setUint32(total - 8, Math.floor(bitLen / 0x100000000))

    const w = new Uint32Array(64)
    for (let i = 0; i < total; i += 64) {
      for (let j = 0; j < 16; j++) {
        const o = i + j * 4
        w[j] =
          (buf[o] << 24) | (buf[o + 1] << 16) | (buf[o + 2] << 8) | buf[o + 3]
      }
      for (let j = 16; j < 64; j++) {
        const s0 = rotr(7, w[j - 15]) ^ rotr(18, w[j - 15]) ^ (w[j - 15] >>> 3)
        const s1 = rotr(17, w[j - 2]) ^ rotr(19, w[j - 2]) ^ (w[j - 2] >>> 10)
        w[j] = (w[j - 16] + s0 + w[j - 7] + s1) >>> 0
      }
      let a = H[0],
        b = H[1],
        c = H[2],
        d = H[3],
        e = H[4],
        f = H[5],
        g = H[6],
        h = H[7]
      for (let j = 0; j < 64; j++) {
        const S1 = rotr(6, e) ^ rotr(11, e) ^ rotr(25, e)
        const ch = (e & f) ^ (~e & g)
        const t1 = (h + S1 + ch + K[j] + w[j]) >>> 0
        const S0 = rotr(2, a) ^ rotr(13, a) ^ rotr(22, a)
        const maj = (a & b) ^ (a & c) ^ (b & c)
        const t2 = (S0 + maj) >>> 0
        h = g
        g = f
        f = e
        e = (d + t1) >>> 0
        d = c
        c = b
        b = a
        a = (t1 + t2) >>> 0
      }
      H[0] = (H[0] + a) >>> 0
      H[1] = (H[1] + b) >>> 0
      H[2] = (H[2] + c) >>> 0
      H[3] = (H[3] + d) >>> 0
      H[4] = (H[4] + e) >>> 0
      H[5] = (H[5] + f) >>> 0
      H[6] = (H[6] + g) >>> 0
      H[7] = (H[7] + h) >>> 0
    }
    const out = new Uint8Array(32)
    const dv = new DataView(out.buffer)
    for (let i = 0; i < 8; i++) dv.setUint32(i * 4, H[i])
    return out
  }

  function bytesToHex(bytes) {
    return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('')
  }

  const block = 64
  let keyBytes = toBytes(key)
  if (keyBytes.length > block) keyBytes = sha256Bytes(keyBytes)
  const paddedKey = new Uint8Array(block)
  paddedKey.set(keyBytes)
  const oKey = new Uint8Array(block)
  const iKey = new Uint8Array(block)
  for (let i = 0; i < block; i++) {
    oKey[i] = paddedKey[i] ^ 0x5c
    iKey[i] = paddedKey[i] ^ 0x36
  }
  const msg = toBytes(message)
  const inner = new Uint8Array(block + msg.length)
  inner.set(iKey)
  inner.set(msg, block)
  const outer = new Uint8Array(block + 32)
  outer.set(oKey)
  outer.set(sha256Bytes(inner), block)
  return bytesToHex(sha256Bytes(outer)).slice(0, hexChars)
}

const root = $('Email Unsubscribe Webhook').first().json
const query = root.query || root.params || {}
const email = String(query.email || '').trim().toLowerCase()
const sig = String(query.sig || '').trim()
const config = $('Get Config').first().json
const secret = String(config.secrets?.webhookSecret || '').trim()

function fail(message) {
  return [{ json: { valid: false, message, email } }]
}

if (!email || !email.includes('@')) return fail('Invalid email address.')
if (!secret) return fail('Unsubscribe is not configured.')

const expected = hmacSha256Hex(email, secret, 32)
if (!sig || sig !== expected) return fail('Invalid or expired unsubscribe link.')

return [{ json: { valid: true, email } }]

const d = $('Extract Contact').first().json
const valid = $('Validate Unsubscribe Link').first().json.valid === true

return [
  {
    json: {
      workflowName: 'SYS 05 — Email Unsubscribe Handler',
      contactName: d.contactName || d.email,
      phone: '',
      eventType: 'email_unsubscribed',
      status: valid ? 'success' : 'error',
      notes: d.contactFound ? `HubSpot contact ${d.contactId}` : 'No HubSpot contact match',
    },
  },
]
